contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint64 _number) public {
        require(_number < 1000000);

        uint64 beforeNumber = c.number(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setL1BlockValues(_number, 0, 0, bytes32(0), 0, bytes32(0), 0, 0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.number() == beforeNumber);
    }

    receive() external payable {}
}

