pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 _number) internal {
        _number = uint64(bound(uint256(_number), 0, 999999));
        uint64 beforeNumber;
        try c.number() returns (uint64 __r) { beforeNumber = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(_number, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.number() == beforeNumber);
    }

    function testFuzz_run(uint64 _number) public {
        _run(_number);
    }

    receive() external payable {}
}
